-- Centering YOU: name, colors, fonts and wordmark come from approval_clients / client_brand.
do $$ begin
  if exists (select 1 from public.approval_clients where slug = 'centering-you') and not exists (select 1 from public.email_brand_kits where slug = 'centering-you') then
    perform public.email_kit_build('centering-you');
    update public.email_brand_kits set
      theme = theme || $j${"muted":"#52797a","font_heading":"Lora,Georgia,'Times New Roman',serif","font_css_url":"https://fonts.googleapis.com/css2?family=Lora:wght@400;500&display=swap","heading_weight":500,"heading_size":30,"heading_tracking":"-.01em","dark":{"page_bg":"#1b2f30","card_bg":"#223c3d","card_border":"#2f4f50","text":"#EFE4D6","heading":"#EFE4D6","muted":"#b9cdc9","eyebrow":"#EF8F55","box_bg":"#2a4647","link":"#F4C459","rule":"#2f4f50"}}$j$::jsonb,
      voice = $t$Warm, direct and calm. Say “I” and “we”. Plain words. Never say “journey” or “affirmation deck”. No emoji.$t$, default_eyebrow = $t$A note from Jared$t$, site_url = $t$https://centeringyou.com$t$
    where slug = 'centering-you';
  end if;
end $$;

