insert into public.email_library (brand_kit, title, subject, blocks, html, source, template_slug, status)
select $t$bestly$t$, $t$Bestly Letter$t$, $t$A note from Jared at Bestly$t$, '[]'::jsonb, $h$<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light dark"><meta name="supported-color-schemes" content="light dark">
<title>Bestly Letter</title>
<link href="https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,400&display=swap" rel="stylesheet">
<style>
@media (prefers-color-scheme: dark) {
