  .bt { color:#fafafa !important; } .bm { color:#a8a8a8 !important; } .bb { border-color:#242424 !important; } .eb { color:#7b8fe5 !important; } .bx { background:#1d1d1d !important; } .lk { color:#9aaaf0 !important; }
