</style></head>
<body style="margin:0;padding:0" class="bg">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" class="bg" style="background:#faf9f7">
<tr><td align="center" style="padding:32px 12px">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px">

  <!-- header: the Bestly Sign animated dot-grid GIF (Outlook shows frame 1, which looks the same) -->
