  <tr><td class="card pad" style="background:#ffffff;border:1px solid #e7e5e0;border-top:0;border-radius:0 0 20px 20px;padding:36px 36px 32px">
    <p class="eb" style="margin:0 0 10px;font:600 12px/16px -apple-system,BlinkMacSystemFont,'SF Pro Text','Inter','Segoe UI',Roboto,Helvetica,Arial,sans-serif;letter-spacing:.16em;text-transform:uppercase;color:#3b4a9c">A note from Jared</p>
    <h1 class="bt h1" style="margin:0 0 20px;font:400 32px/36px 'Newsreader',Georgia,'Times New Roman',serif;letter-spacing:-.02em;color:#111827">Your headline here.</h1>

    <p class="bt" style="margin:0 0 14px;font:400 16px/25px -apple-system,BlinkMacSystemFont,'SF Pro Text','Inter','Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#111827">Hi [Name],</p>
    <p class="bt" style="margin:0 0 14px;font:400 16px/25px -apple-system,BlinkMacSystemFont,'SF Pro Text','Inter','Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#111827">Write your message here.</p>
    <p class="bt" style="margin:0 0 28px;font:400 16px/25px -apple-system,BlinkMacSystemFont,'SF Pro Text','Inter','Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#111827">Thanks,</p>

    <!-- signature (Jared's Bestly signature) -->
    <table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>
      <td style="vertical-align:top;padding:0;width:56px"><img src="https://www.bestly.tech/email-templates/assets/jared-headshot.gif" width="56" height="56" alt="Jared Best" style="display:block;width:56px;height:56px;border:0;border-radius:28px"></td>
      <td style="width:16px;min-width:16px;font-size:0;line-height:0">&nbsp;</td>
      <td class="bb" style="vertical-align:top;padding:0 0 0 14px;border-left:2px solid #7a8be0">
        <div class="bt" style="font:600 15px/20px -apple-system,BlinkMacSystemFont,'SF Pro Text','Inter','Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#111827">Jared Best</div>
        <div class="bm" style="padding-top:2px;font:400 13px/18px -apple-system,BlinkMacSystemFont,'SF Pro Text','Inter','Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#667085">Founder, <span class="bt" style="font:400 15px/18px 'Newsreader',Georgia,serif;color:#111827">Bestly</span></div>
        <div style="padding-top:8px;font:400 13px/20px -apple-system,BlinkMacSystemFont,'SF Pro Text','Inter','Segoe UI',Roboto,Helvetica,Arial,sans-serif"><a class="lk" href="mailto:jared@bestly.tech" style="color:#3b4a9c;text-decoration:none">jared@bestly.tech</a><span class="bm" style="color:#667085">&nbsp;&nbsp;·&nbsp;&nbsp;</span><a class="lk" href="tel:+18165007236" style="color:#3b4a9c;text-decoration:none;white-space:nowrap">(816)&nbsp;500&#8209;7236</a></div>
      </td>
    </tr></table>
  </td></tr>

  <!-- footer: feathered rainbow hairline, same as Bestly Sign -->
  <tr><td style="padding:26px 8px 0;text-align:center" align="center">
    <div style="height:2px;max-width:220px;margin:0 auto 14px;border-radius:2px;background:linear-gradient(90deg,rgba(228,3,3,0),#e40303 14%,#ff8c00 30%,#ffed00 46%,#008026 62%,#24408e 78%,rgba(115,41,130,0))"></div>
    <p class="bm" style="margin:0;font:400 12px/18px -apple-system,BlinkMacSystemFont,'SF Pro Text','Inter','Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#667085">Bestly LLC · Gay-owned · Built in Los Angeles</p>
    <p class="bm" style="margin:4px 0 0;font:400 12px/18px -apple-system,BlinkMacSystemFont,'SF Pro Text','Inter','Segoe UI',Roboto,Helvetica,Arial,sans-serif;color:#667085">Bestly builds AI agents and privacy-first apps for small businesses. <a class="lk" href="https://bestly.tech" style="color:#3b4a9c;text-decoration:none;font-weight:600;white-space:nowrap">See what we make</a></p>
  </td></tr>

</table></td></tr></table></body></html>
$h$, 'template', $t$bestly-letter$t$, 'draft'
