<div class="bg" style="margin:0;padding:0;background:#f5f7fa;">

  <table role="presentation" class="bg" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f5f7fa;">
    <tr>
      <td align="center" style="padding:40px 16px 48px;">

        <!-- Brand -->
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:560px;">
          <tr>
            <td align="center" style="padding:0 0 24px;">
              <a href="https://www.inventoryproof.com" style="text-decoration:none;">
                <img src="https://rcqfqhguwpmaarseifqg.supabase.co/storage/v1/object/public/email-assets/inventoryproof-icon.png" width="56" height="56" alt="InventoryProof" style="display:block;width:56px;height:56px;border:0;border-radius:14px;margin:0 auto;">
              </a>
              <div class="t-strong" style="padding-top:12px;font-family:Manrope,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:17px;font-weight:700;letter-spacing:-0.01em;color:#0661d0;">InventoryProof</div>
            </td>
          </tr>
        </table>

        <!-- Card -->
        <table role="presentation" class="card" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:560px;background:#ffffff;border:1px solid #e1e7ef;border-radius:20px;">
          <tr>
            <td class="card-pad" style="padding:40px 40px 36px;font-family:Manrope,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
              <h1 class="h1 t-strong" style="margin:0 0 16px;font-size:28px;line-height:1.2;font-weight:700;letter-spacing:-0.02em;color:#1d2530;">[Headline, e.g. You haven&#x27;t been charged.]</h1>
              <p class="t-body" style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#3d4a5c;">Hi [Name],</p>
              <p class="t-body" style="margin:0 0 28px;font-size:16px;line-height:1.6;color:#3d4a5c;">Thanks for getting in touch. We looked up your InventoryProof account, and here&#x27;s what we found.</p>
              <table role="presentation" class="panel" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:#f6f8fb;border:1px solid #e1e7ef;border-radius:16px;">
                <tr>
                  <td align="center" style="padding:28px 24px 24px;">
                    <div class="t-muted" style="font-size:13px;line-height:1.4;font-weight:600;letter-spacing:0.02em;text-transform:uppercase;color:#65758b;">Total charged to date</div>
                    <div class="hero-num t-strong" style="padding-top:6px;font-size:52px;line-height:1.05;font-weight:800;letter-spacing:-0.03em;color:#1d2530;font-variant-numeric:tabular-nums;white-space:nowrap;">$0.00</div>
                  </td>
                </tr>
                <tr>
                  <td style="padding:0 24px;">
                    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
                      <tr>
                        <td class="divider t-muted" style="border-top:1px solid #e1e7ef;padding:14px 0 14px;font-size:14px;line-height:1.4;color:#65758b;">Account</td>
                        <td class="divider t-strong" align="right" style="border-top:1px solid #e1e7ef;padding:14px 0 14px;font-size:14px;line-height:1.4;font-weight:600;color:#1d2530;white-space:nowrap;">[email]</td>
                      </tr>
                      <tr>
                        <td class="divider t-muted" style="border-top:1px solid #e1e7ef;padding:14px 0 14px;font-size:14px;line-height:1.4;color:#65758b;">Plan</td>
                        <td class="divider" align="right" style="border-top:1px solid #e1e7ef;padding:14px 0 14px;"><span class="pill" style="display:inline-block;padding:4px 12px;border-radius:999px;background:#ebf4fe;color:#0551ad;font-size:13px;line-height:1.4;font-weight:700;">Free</span></td>
                      </tr>
                      <tr>
                        <td class="divider t-muted" style="border-top:1px solid #e1e7ef;padding:14px 0 14px;font-size:14px;line-height:1.4;color:#65758b;">Card on file</td>
                        <td class="divider t-strong" align="right" style="border-top:1px solid #e1e7ef;padding:14px 0 14px;font-size:14px;line-height:1.4;font-weight:600;color:#1d2530;white-space:nowrap;">None</td>
                      </tr>
                      <tr>
                        <td class="divider t-muted" style="border-top:1px solid #e1e7ef;padding:14px 0 14px;font-size:14px;line-height:1.4;color:#65758b;">Signed up</td>
                        <td class="divider t-strong" align="right" style="border-top:1px solid #e1e7ef;padding:14px 0 14px;font-size:14px;line-height:1.4;font-weight:600;color:#1d2530;white-space:nowrap;">[Mon D, YYYY]</td>
                      </tr>
                      <tr>
                        <td class="divider t-muted" style="border-top:1px solid #e1e7ef;padding:14px 0 14px;font-size:14px;line-height:1.4;color:#65758b;">Last sign-in</td>
                        <td class="divider t-strong" align="right" style="border-top:1px solid #e1e7ef;padding:14px 0 14px;font-size:14px;line-height:1.4;font-weight:600;color:#1d2530;white-space:nowrap;">[when]</td>
                      </tr>
                      <tr>
                        <td class="divider t-muted" style="border-top:1px solid #e1e7ef;padding:14px 0 14px;font-size:14px;line-height:1.4;color:#65758b;">Items captured</td>
                        <td class="divider t-strong" align="right" style="border-top:1px solid #e1e7ef;padding:14px 0 14px;font-size:14px;line-height:1.4;font-weight:600;color:#1d2530;white-space:nowrap;">[0]</td>
                      </tr>
                      <tr>
                        <td class="divider t-muted" style="border-top:1px solid #e1e7ef;padding:14px 0 18px;font-size:14px;line-height:1.4;color:#65758b;">Onboarding</td>
                        <td class="divider t-strong" align="right" style="border-top:1px solid #e1e7ef;padding:14px 0 18px;font-size:14px;line-height:1.4;font-weight:600;color:#1d2530;white-space:nowrap;">[Not completed]</td>
                      </tr>
                    </table>
                  </td>
                </tr>
              </table>
              <p class="t-body" style="margin:28px 0 16px;font-size:16px;line-height:1.6;color:#3d4a5c;">[Explain what happened in plain words.]</p>
              <p class="t-body" style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#3d4a5c;">If you&#x27;re seeing a charge on your card or bank statement, it&#x27;s likely from another company. Reply with the date, the amount and how it appears on your statement, and we&#x27;ll help you track it down.</p>
              <table role="presentation" class="callout" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:32px;background:#ebf4fe;border:1px solid #cfe3fc;border-radius:18px;">
                <tr>
                  <td align="center" class="callout-pad" style="padding:32px 32px 30px;">
                    <a href="https://www.trustpilot.com/review/inventoryproof.com" style="text-decoration:none;"><img src="https://rcqfqhguwpmaarseifqg.supabase.co/storage/v1/object/public/email-assets/trustpilot-logo-black.png" width="130" height="32" alt="Trustpilot" style="display:block;width:130px;height:32px;border:0;margin:0 auto;"></a>
                    <p class="callout-text" style="margin:20px 0 24px;font-size:20px;line-height:1.45;font-weight:700;letter-spacing:-0.01em;color:#1d2530;">If this clears things up, we&#x27;d really appreciate it if you could update your Trustpilot review to reflect that.</p>
                    <table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:0 auto;">
                      <tr>
                        <td align="center" style="border-radius:12px;border:1.5px solid #1d2530;background:#ffffff;">
                          <a class="btn-m" href="https://www.trustpilot.com/review/inventoryproof.com" style="display:inline-block;min-width:200px;padding:14px 28px;font-family:Manrope,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:16px;line-height:20px;font-weight:700;color:#1d2530;text-align:center;border-radius:12px;">Update your review</a>
                        </td>
                      </tr>
                    </table>
                  </td>
                </tr>
              </table>
              <table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:28px auto 0;">
                <tr>
                  <td class="btn" align="center" style="border-radius:12px;background:#0661d0;">
                    <a class="btn-m" href="https://www.inventoryproof.com/auth" style="display:inline-block;min-width:200px;padding:15px 28px;font-family:Manrope,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:16px;line-height:20px;font-weight:700;color:#ffffff;text-align:center;border-radius:12px;">Log in to your account</a>
                  </td>
                </tr>
              </table>
              <p style="margin:8px 0 0;text-align:center;"><a class="t-link" href="https://www.inventoryproof.com/forgot-password" style="display:inline-block;padding:12px 4px;font-size:15px;line-height:20px;font-weight:700;color:#0661d0;">Forgot password</a><span class="t-muted" style="padding:0 10px;color:#97a3b6;">&middot;</span><a class="t-link" href="mailto:support@inventoryproof.com" style="display:inline-block;padding:12px 4px;font-size:15px;line-height:20px;font-weight:700;color:#0661d0;">Contact support</a></p>
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:32px;">
                <tr>
                  <td class="divider" style="border-top:1px solid #e1e7ef;padding-top:24px;">
                    <p class="t-body" style="margin:0;font-size:16px;line-height:1.5;color:#3d4a5c;">Thanks,</p>
                    <p class="t-strong" style="margin:4px 0 0;font-size:16px;line-height:1.5;font-weight:700;color:#1d2530;">Jared</p>
                    <p class="t-muted" style="margin:0;font-size:14px;line-height:1.5;color:#65758b;">InventoryProof Support</p>
                  </td>
                </tr>
              </table>

            </td>
          </tr>
        </table>

        <!-- Footer -->
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:560px;">
          <tr>
            <td align="center" class="t-muted" style="padding:28px 24px 0;font-family:Manrope,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:13px;line-height:1.6;color:#65758b;">
              Record a video of your home. Get an itemized inventory of everything you own.<br>
              <a class="t-link" href="https://www.inventoryproof.com" style="color:#0661d0;font-weight:600;">inventoryproof.com</a>
              <span style="padding:0 6px;">&middot;</span>Bestly LLC
            </td>
          </tr>
        </table>

      </td>
    </tr>
  </table>
</div>
</body></html>$h$, 'template', $t$inventoryproof-support$t$, 'draft'
